<style scoped lang="scss" src="./columns.scss"></style>

<script lang="js">
import { Component, Prop, Vue } from "vue-property-decorator";
import WrapNode from "../wrap-node/wrap-node.vue";
import {
  ColumnGapSize,
  ColumnGapSizeValues,
  ColumnAlignment,
  ColumnAlignmentValues,
  ColumnJustifyContent,
  ColumnJustifyContentValues
} from "./columns.constants";
import { has } from "../../util/has";

@Component({
  components: {
    WrapNode,
  },
})
export default class Columns extends Vue{
  @Prop({ type: Boolean, default: true }) even;
  @Prop({
    type: String,
    default: ColumnGapSize.NONE,
    validator: has(ColumnGapSizeValues)
  }) gapSize;
  @Prop({
    type: String,
    default: ColumnAlignment.START,
    validator: has(ColumnAlignmentValues)
  }) align;
  @Prop({
    type: String,
    default: ColumnJustifyContent.SPACE_BETWEEN,
    validate: has(ColumnJustifyContentValues)
  }) justify;

  get tagNodes() {
    if (Array.isArray(this.$slots.default)) {
      return this.$slots.default.filter(node => node.tag !== undefined);
    }

    return this.$slots.default;
  }

  get cellCount() {
    if (Array.isArray(this.$slots.default)) {
      return this.$slots.default.filter(node => node.tag !== undefined).length;
    }

    return 1;
  }

  get columnStyle() {
    if(this.even) {
      return {
        flex: '1 1 0',
        minWidth: `0px`,
        width: '100%',
      }
    }

    return {
    }
  }

  get gapStyle() {
    return this.gapSize;
  }

  get contentClass() {
    return this.justify;
  }

  get alignClass() {
    return this.align;
  }

  cellSlot(i) {
    return this.tagNodes[i];
  }

  update() {
    this.key++;
  }
}
</script>

<template>
  <div class="Columns">
    <div :class="['Columns__Content', alignClass, contentClass]">
      <div
        :class="['Columns__Col', gapStyle]"
        v-for="(e, i) in cellCount"
        :key="`column_${i}`"
        :style="columnStyle"
      >
        <WrapNode :value="i"><slot /></WrapNode>
      </div>
    </div>
  </div>
</template>
